return $input.all().map(item => {
  if (item.json.content) {
    item.json.text = global.Buffer.from(item.json.content, 'base64').toString('utf8');
  } else {
    item.json.text = 'No content found';
  }
  return item;
});

// Access all input items (each with json.text)
const allTexts = $input.all().map(item => item.json.text);

// Combine them into one string, separated by line breaks
const combinedText = allTexts.join('\n\n');

// Return a single item with combined text suitable for AI prompt
return [
  {
    json: {
      combinedText: combinedText,
    },
  },
];
